def test_waf_detects_cloudflare_and_modsecurity_blocks() -> None:
    cf_receipt = {
        "status": 403,
        "content_type": "text/html; charset=utf-8",
        "response_headers": {
            "Server": "cloudflare",
            "CF-Ray": "8a1b2c3d4e5f-IAD",
            "Content-Type": "text/html",
        },
        "body": "<html><head><title>Attention Required! | Cloudflare</title></head><body>Sorry, you have been blocked</body></html>",
    }
    cf_out = agentic_waf.detect_waf_block(cf_receipt)
    assert cf_out == {
        "waf_blocked": True,
        "vendor": "cloudflare",
        "classification": "waf_block",
        "status": 403,
    }

    modsec_receipt = {
        "status": 403,
        "content_type": "text/html",
        "response_headers": {"Server": "Apache"},
        "body": "<html><body><h1>Not Acceptable</h1><p>This error was generated by Mod_Security.</p></body></html>",
    }
    modsec_out = agentic_waf.detect_waf_block(modsec_receipt)
    assert modsec_out == {
        "waf_blocked": True,
        "vendor": "modsecurity",
        "classification": "waf_block",
        "status": 403,
    }

    f5_receipt = {
        "status": 403,
        "content_type": "text/html",
        "response_headers": {},
        "body": "<html><body>The requested URL was rejected. Please consult with your administrator. Support ID: 98765</body></html>",
    }
    f5_out = agentic_waf.detect_waf_block(f5_receipt)
    assert f5_out is not None
    assert f5_out["waf_blocked"] is True
    assert f5_out["vendor"] == "f5_big_ip_asm"

    generic_receipt = {
        "status": 429,
        "content_type": "text/plain",
        "response_headers": {},
        "body": "Request blocked by upstream edge policy.",
    }
    gen_out = agentic_waf.detect_waf_block(generic_receipt)
    assert gen_out == {
        "waf_blocked": True,
        "vendor": "generic",
        "classification": "waf_block",
        "status": 429,
    }


def test_waf_ignores_normal_app_json_403_and_non_block_statuses() -> None:
    app_403 = {
        "status": 403,
        "content_type": "application/json",
        "response_headers": {"Content-Type": "application/json"},
        "body": json.dumps({"error": "forbidden"}),
    }
    assert agentic_waf.detect_waf_block(app_403) is None

    # App behind Cloudflare returning a genuine JSON 403 must not false-positive
    app_behind_cf = {
        "status": 403,
        "content_type": "application/json",
        "response_headers": {
            "Server": "cloudflare",
            "CF-Ray": "8a1b2c3d4e5f-IAD",
            "Content-Type": "application/json",
        },
        "body": json.dumps({"error": "forbidden", "detail": "insufficient role"}),
    }
    assert agentic_waf.detect_waf_block(app_behind_cf) is None

    # Non-block statuses are ignored even if body mentions cloudflare
    ok_200 = {
        "status": 200,
        "content_type": "text/html",
        "response_headers": {"Server": "cloudflare", "CF-Ray": "1234"},
        "body": "Attention Required! | Cloudflare docs",
    }
    assert agentic_waf.detect_waf_block(ok_200) is None


def test_waf_graceful_fallback_when_waf_profiles_unavailable(monkeypatch: pytest.MonkeyPatch) -> None:
    monkeypatch.setattr(agentic_waf, "_load_waf_profiles", lambda: (None, None))
    receipt = {
        "status": 403,
        "content_type": "text/html",
        "response_headers": {"CF-Ray": "abc-SJC"},
        "body": "Attention Required! | Cloudflare",
    }
    out = agentic_waf.detect_waf_block(receipt)
    assert out == {
        "waf_blocked": True,
        "vendor": "cloudflare",
        "classification": "waf_block",
        "status": 403,
    }
    app_403 = {
        "status": 403,
        "content_type": "application/json",
        "response_headers": {"Content-Type": "application/json"},
        "body": '{"error": "forbidden"}',
    }
    assert agentic_waf.detect_waf_block(app_403) is None


