def test_crypto_analyze_jwt_posture_findings_and_claim_truncation() -> None:
    long_claim = "x" * 200
    tok = _make_jwt(
        {"alg": "none", "typ": "JWT", "kid": "key-01", "jku": "https://idp.test/jwks.json"},
        {"sub": "user-42", "role": "admin", "note": long_claim},
        sig=b"",
    )
    out = agentic_crypto.analyze_jwt("Bearer " + tok)
    assert out["kind"] == "jwt"
    assert out["valid_jwt"] is True
    assert out["header"]["alg"] == "none"
    assert out["payload"]["sub"] == "user-42"
    assert len(out["payload"]["note"]) < len(long_claim)
    assert "<redacted:len=200>" in out["payload"]["note"]
    assert "alg_none" in out["findings"]
    assert "missing_exp" in out["findings"]
    assert "kid_header_present" in out["findings"]
    assert "jku_or_x5u_present" in out["findings"]
    assert "authorization_claims_present" in out["findings"]

    hs_expired = _make_jwt(
        {"alg": "HS256", "typ": "JWT"},
        {"sub": "user-99", "exp": int(time.time()) - 3600, "scope": "read:all"},
    )
    out2 = agentic_crypto.analyze_jwt(hs_expired)
    assert out2["valid_jwt"] is True
    assert "symmetric_alg" in out2["findings"]
    assert "expired" in out2["findings"]
    assert "missing_exp" not in out2["findings"]
    assert "authorization_claims_present" in out2["findings"]


def test_crypto_opaque_token_32byte_hex_and_base64_alignment() -> None:
    raw32 = bytes(range(32))
    hex_val = raw32.hex()
    b64_val = base64.b64encode(raw32).decode("ascii")
    b64url_val = _b64url(raw32)

    hex_out = agentic_crypto.analyze_opaque_token(hex_val)
    assert hex_out["kind"] == "opaque"
    assert hex_out["encoding"] == "hex"
    assert hex_out["length_bytes"] == 32
    assert hex_out["block16_aligned"] is True
    assert hex_out["block8_aligned"] is True
    assert hex_val not in json.dumps(hex_out)

    b64_out = agentic_crypto.analyze_opaque_token(b64_val)
    assert b64_out["encoding"] == "base64"
    assert b64_out["length_bytes"] == 32
    assert b64_out["block16_aligned"] is True
    assert b64_out["block8_aligned"] is True
    assert b64_out["sha256"] == hex_out["sha256"]

    b64url_out = agentic_crypto.analyze_opaque_token(b64url_val)
    assert b64url_out["length_bytes"] == 32
    assert b64url_out["block16_aligned"] is True
    assert b64url_out["sha256"] == hex_out["sha256"]


def test_crypto_serialization_detection_and_auto_dispatch() -> None:
    # Java serialized stream with TC_OBJECT + TC_CLASSDESC ("com.example.Session")
    cls_bytes = b"com.example.Session"
    java_bytes = b"\xac\xed\x00\x05\x73\x72" + len(cls_bytes).to_bytes(2, "big") + cls_bytes + b"\x00" * 8
    java_b64 = base64.b64encode(java_bytes).decode("ascii")
    assert java_b64.startswith("rO0AB")

    java_out = agentic_crypto.detect_serialization(java_b64)
    assert java_out["kind"] == "serialization"
    assert java_out["detected"] is True
    assert java_out["format"] == "java"
    assert java_out["class_name"] == "com.example.Session"

    java_hex_out = agentic_crypto.detect_serialization(java_bytes.hex())
    assert java_hex_out["detected"] is True
    assert java_hex_out["format"] == "java"
    assert java_hex_out["class_name"] == "com.example.Session"

    php_raw = 'O:4:"User":1:{s:4:"role";s:5:"admin";}'
    php_out = agentic_crypto.detect_serialization(php_raw)
    assert php_out["detected"] is True
    assert php_out["format"] == "php"
    assert php_out["class_name"] == "User"

    php_b64_out = agentic_crypto.detect_serialization(base64.b64encode(php_raw.encode()).decode("ascii"))
    assert php_b64_out["detected"] is True
    assert php_b64_out["format"] == "php"

    pickle_b64 = base64.b64encode(b"\x80\x04\x95\x05\x00\x00\x00\x00\x00\x00\x00}\x94.").decode("ascii")
    pickle_out = agentic_crypto.detect_serialization(pickle_b64)
    assert pickle_out["detected"] is True
    assert pickle_out["format"] == "python_pickle"

    viewstate_out = agentic_crypto.detect_serialization("/wEPDwUKLTEyMzQ1Ng==")
    assert viewstate_out["detected"] is True
    assert viewstate_out["format"] == "viewstate"

    # Unified auto-dispatch
    jwt_tok = _make_jwt({"alg": "HS256"}, {"sub": "u1", "roles": ["editor"]})
    assert agentic_crypto.analyze_token(jwt_tok, kind="auto")["kind"] == "jwt"
    assert agentic_crypto.analyze_token(java_b64, kind="auto")["kind"] == "serialization"
    assert agentic_crypto.analyze_token(php_raw, kind="auto")["kind"] == "serialization"
    opaque_auto = agentic_crypto.analyze_token(bytes(range(32)).hex(), kind="auto")
    assert opaque_auto["kind"] == "opaque"
    assert opaque_auto["length_bytes"] == 32


