def test_vault_roundtrip_and_fail_closed_missing_key(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> None:
    monkeypatch.delenv("CCO_VAULT_KEY", raising=False)
    monkeypatch.setenv("CCO_USE_KEYRING", "0")

    cco_home = tmp_path / "vault_home"
    secret_marker = "synthetic-cred-value-991"
    agentic_vault.save_vault_credentials(
        cco_home,
        "staging_actor",
        {"username": "qa_user", "api_key": secret_marker},
    )

    loaded = agentic_vault.load_vault_credentials(cco_home, "staging_actor")
    assert loaded == {"username": "qa_user", "api_key": secret_marker}

    # Index file and SQLite DB must not contain plaintext secret material
    idx_text = (cco_home / "agentic_vault_index.json").read_text(encoding="utf-8")
    assert secret_marker not in idx_text
    db_bytes = (cco_home / "credential_vault.db").read_bytes()
    assert secret_marker.encode() not in db_bytes

    # Unknown key_name raises KeyError
    with pytest.raises(KeyError):
        agentic_vault.load_vault_credentials(cco_home, "nonexistent_actor")

    # Deleting vault.key makes reads fail closed and must NOT recreate vault.key
    key_path = cco_home / "vault.key"
    assert key_path.is_file()
    key_path.unlink()
    with pytest.raises(ValueError, match="key unavailable"):
        agentic_vault.load_vault_credentials(cco_home, "staging_actor")
    assert not key_path.exists()

    # Reading from an empty/uninitialized directory also fails closed
    empty_home = tmp_path / "empty_home"
    with pytest.raises(ValueError):
        agentic_vault.load_vault_credentials(empty_home, "anything")
    assert not empty_home.exists()


def test_vault_verify_external_oob_event_and_replay_rejection(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    monkeypatch.setenv("CCO_HOME", str(tmp_path / "cco_home"))
    private_key = Ed25519PrivateKey.generate()
    public_raw = private_key.public_key().public_bytes(
        serialization.Encoding.Raw,
        serialization.PublicFormat.Raw,
    )
    trusted_keys = json.dumps({"collector-a": _b64url(public_raw)})

    challenge = {
        "token": "ccossrftest123",
        "host": "ccossrftest123.oob.test",
        "target_url": "https://owned.test/fetch?url=synthetic",
        "param": "url",
        "run_id": "run-b2",
        "target_binding": "a" * 64,
        "probe_binding": "b" * 64,
        "scope_revision": "scope-rev-1",
        "policy_hash": "policy-hash-1",
        "collector_eligible": True,
        "sent_at": 1000,
        "expires_at": 2000,
    }
    unsigned_event = {
        "schema": "cco-oob-collector-event/1",
        "collector_id": "collector-a",
        "event_id": "evt-001",
        "nonce": challenge["token"],
        "host": challenge["host"],
        "target_binding": challenge["target_binding"],
        "probe_binding": challenge["probe_binding"],
        "param": challenge["param"],
        "run_id": challenge["run_id"],
        "scope_revision": "scope-rev-1",
        "policy_hash": "policy-hash-1",
        "protocol": "http",
        "observed_at": 1200,
    }
    msg = json.dumps(unsigned_event, sort_keys=True, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
    signed_event = json.dumps({**unsigned_event, "signature": _b64url(private_key.sign(msg))})
    replay_db = tmp_path / "replay" / "oob_replay.db"

    # Untrusted key fails closed before consuming
    wrong_key = Ed25519PrivateKey.generate()
    bad_signed = json.dumps({**unsigned_event, "signature": _b64url(wrong_key.sign(msg))})
    rejected = agentic_vault.verify_external_oob_event(
        challenge,
        bad_signed,
        trusted_keys,
        replay_db,
        scope_revision="scope-rev-1",
        policy_hash="policy-hash-1",
        now=1250,
    )
    assert rejected["authenticated"] is False

    # Valid signed event succeeds once
    accepted = agentic_vault.verify_external_oob_event(
        challenge,
        signed_event,
        trusted_keys,
        replay_db,
        scope_revision="scope-rev-1",
        policy_hash="policy-hash-1",
        now=1250,
    )
    assert accepted["authenticated"] is True
    assert accepted["collector_id"] == "collector-a"
    assert accepted["protocol"] == "http"
    assert Path(accepted["event_path"]).is_file()

    # Replay of the exact same signed event is rejected
    replayed = agentic_vault.verify_external_oob_event(
        challenge,
        signed_event,
        trusted_keys,
        replay_db,
        scope_revision="scope-rev-1",
        policy_hash="policy-hash-1",
        now=1260,
    )
    assert replayed["authenticated"] is False
    assert "consumed" in str(replayed.get("reason") or "")


