def test_preview_js_client_logic_map_extraction_and_no_secret_leak() -> None:
    js_body = r"""
//# sourceMappingURL=app.bundle.js.map
const emailValidator = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
function signPayload(data) {
  return CryptoJS.HmacSHA256(JSON.stringify(data), window.__APP_SECRET__);
}
async function submitOrder(orderId, email) {
  const sig = signPayload({orderId, email});
  return fetch(`/api/v2/orders/${orderId}?dry_run=1`, {
    method: "POST",
    headers: {"Content-Type": "application/json", "X-Signature": sig, "Authorization": "Bearer TOP_SECRET_CANARY_88"},
    body: JSON.stringify({orderId, email, amount: 10})
  });
}
function dynamicCall(id) {
  return fetch(resolveDynamicEndpoint(id), {method: "PUT"});
}
localStorage.setItem("workspace_role", "SUPER_SECRET_ROLE_VALUE");
"""
    receipt = {
        "receipt_id": "req-0101",
        "url": "https://app.test/static/app.bundle.js",
        "content_type": "application/javascript; charset=utf-8",
        "response_headers": {"Content-Type": "application/javascript"},
        "body": js_body,
    }
    summary = _extract_surface_summary(receipt, "https://app.test")
    assert "client_logic" in summary
    cl = summary["client_logic"]

    # Endpoints extracted & merged into js_calls / links
    assert any(ep["path"] == "/api/v2/orders/{id}" and ep["method"] == "POST" for ep in cl["endpoints"])
    assert any("/api/v2/orders/" in str(lnk.get("url") or "") for lnk in summary["links"])
    assert any("/api/v2/orders/" in str(call.get("url") or "") for call in summary["js_calls"])

    # Signing indicators, validation fields, storage keys, sourceMappingURL, dynamic coverage gaps
    assert "signPayload" in cl["signing_indicators"]
    assert "email" in cl["validation_fields"]
    assert "workspace_role" in cl["storage_keys"]
    assert "app.bundle.js.map" in cl["source_maps"]
    assert any("dynamic_endpoint_runtime_required" in gap for gap in cl["coverage_gaps"])

    # Secret values must never appear anywhere in summary
    dumped = json.dumps(summary)
    assert "TOP_SECRET_CANARY_88" not in dumped
    assert "SUPER_SECRET_ROLE_VALUE" not in dumped


def test_preview_graphql_introspection_schema_extraction() -> None:
    introspection = {
        "data": {
            "__schema": {
                "queryType": {"name": "Query"},
                "mutationType": {"name": "Mutation"},
                "types": [
                    {
                        "name": "Query",
                        "kind": "OBJECT",
                        "fields": [
                            {"name": "viewer", "args": []},
                            {
                                "name": "invoice",
                                "args": [{"name": "id"}, {"name": "includeItems"}],
                            },
                            {"name": "__typename", "args": []},
                        ],
                    },
                    {
                        "name": "Mutation",
                        "kind": "OBJECT",
                        "fields": [
                            {
                                "name": "promoteMember",
                                "args": [{"name": "memberId"}, {"name": "role"}],
                            }
                        ],
                    },
                ],
            }
        }
    }
    receipt = {
        "receipt_id": "req-0102",
        "url": "https://app.test/graphql",
        "content_type": "application/json",
        "response_headers": {"Content-Type": "application/json"},
        "body": json.dumps(introspection),
    }
    summary = _extract_surface_summary(receipt, "https://app.test")
    assert "graphql_ops" in summary
    assert summary["graphql_ops"] == [
        {"kind": "query", "name": "viewer", "args": []},
        {"kind": "query", "name": "invoice", "args": ["id", "includeItems"]},
        {"kind": "mutation", "name": "promoteMember", "args": ["memberId", "role"]},
    ]
    assert "client_logic" not in summary
    assert "postman_ops" not in summary


def test_preview_postman_v21_collection_extraction() -> None:
    collection = {
        "info": {
            "name": "Workspace API",
            "schema": "https://schema.getpostman.com/json/collection/v2.1.0/collection.json",
        },
        "item": [
            {
                "name": "Orders Folder",
                "item": [
                    {
                        "name": "Create Order",
                        "request": {
                            "method": "POST",
                            "url": {"raw": "https://app.test/api/v1/orders"},
                            "body": {
                                "mode": "raw",
                                "raw": json.dumps({"item_id": "itm-1", "qty": 2, "coupon": "SECRET_COUPON_99"}),
                            },
                        },
                    },
                    {
                        "name": "Update Profile",
                        "request": {
                            "method": "PUT",
                            "url": "{{baseUrl}}/api/v1/profile",
                            "body": {
                                "mode": "urlencoded",
                                "urlencoded": [
                                    {"key": "display_name", "value": "Alice"},
                                    {"key": "role", "value": "member"},
                                ],
                            },
                        },
                    },
                ],
            },
            {
                "name": "External Webhook",
                "request": {
                    "method": "GET",
                    "url": "https://thirdparty.example/status",
                },
            },
        ],
    }
    receipt = {
        "receipt_id": "req-0103",
        "url": "https://app.test/postman.json",
        "content_type": "application/json",
        "response_headers": {"Content-Type": "application/json"},
        "body": json.dumps(collection),
    }
    summary = _extract_surface_summary(receipt, "https://app.test")
    assert "postman_ops" in summary
    ops = summary["postman_ops"]
    assert len(ops) == 3
    assert ops[0] == {
        "method": "POST",
        "url": "https://app.test/api/v1/orders",
        "body_keys": ["item_id", "qty", "coupon"],
    }
    assert ops[1] == {
        "method": "PUT",
        "url": "{{baseUrl}}/api/v1/profile",
        "body_keys": ["display_name", "role"],
    }
    assert ops[2] == {
        "method": "GET",
        "url": "https://thirdparty.example/status",
        "body_keys": [],
    }
    # Same-origin Postman URLs added to links, external URL not added to links
    link_urls = {lnk["url"] for lnk in summary["links"]}
    assert "/api/v1/orders" in link_urls
    assert "/api/v1/profile" in link_urls
    assert all("thirdparty.example" not in u for u in link_urls)
    # Plaintext values from Postman body must not be echoed in postman_ops
    assert "SECRET_COUPON_99" not in json.dumps(ops)


