def test_preview_graphql_top_level_schema_and_60_cap() -> None:
    fields = [{"name": f"op_{i}", "args": [{"name": "id"}]} for i in range(75)]
    body = json.dumps({
        "__schema": {
            "queryType": {"name": "RootQuery"},
            "mutationType": None,
            "types": [{"name": "RootQuery", "fields": fields}],
        }
    })
    receipt = {
        "receipt_id": "req-0105",
        "url": "https://app.test/schema.json",
        "content_type": "application/json",
        "response_headers": {"Content-Type": "application/json"},
        "body": body,
    }
    summary = _extract_surface_summary(receipt, "https://app.test")
    assert len(summary["graphql_ops"]) == 60
